BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(28);
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_d1_student_identity_number_source' AND contype='u' AND conrelid='app_private.students'::regclass AND cardinality(conkey)=3),'Student identity and number composite key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_ledger_rendered_source' AND contype='u' AND conrelid='app_private.admission_number_allocations'::regclass AND cardinality(conkey)=2),'allocation ID and rendered number composite key');
SELECT ok((SELECT attnotnull AND NOT attisdropped FROM pg_attribute WHERE attrelid='app_private.admission_student_handoffs'::regclass AND attname='admission_number_text'),'handoff rendered number required');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_number_text_nonempty' AND contype='c' AND conrelid='app_private.admission_student_handoffs'::regclass),'blank rendered number prohibited');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_exact_allocation_number' AND contype='f' AND conrelid='app_private.admission_student_handoffs'::regclass AND confrelid='app_private.admission_number_allocations'::regclass AND cardinality(conkey)=2),'exact allocation-number foreign key');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%admission_number_allocation_id, admission_number_text%' FROM pg_constraint WHERE conname='db03_handoff_exact_allocation_number'),'allocation and text checked together');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%id, rendered_number%' FROM pg_constraint WHERE conname='db03_handoff_exact_allocation_number'),'number sourced from actual ledger');
SELECT ok((SELECT confupdtype='r' AND confdeltype='r' FROM pg_constraint WHERE conname='db03_handoff_exact_allocation_number'),'allocation reassignment restricted');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_exact_d1_student_number_person' AND contype='f' AND conrelid='app_private.admission_student_handoffs'::regclass AND confrelid='app_private.students'::regclass AND cardinality(conkey)=3),'Student Person and number matched by composite FK');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%result_student_id, person_id, admission_number_text%' FROM pg_constraint WHERE conname='db03_handoff_exact_d1_student_number_person'),'all three handoff fields checked');
SELECT ok((SELECT pg_get_constraintdef(oid) LIKE '%id, person_id, admission_number%' FROM pg_constraint WHERE conname='db03_handoff_exact_d1_student_number_person'),'correct D1 Student fields checked');
SELECT ok((SELECT condeferrable AND condeferred FROM pg_constraint WHERE conname='db03_handoff_exact_d1_student_number_person'),'Student link verified at commit');
SELECT ok((SELECT confmatchtype='s' AND confupdtype='a' AND confdeltype='a' FROM pg_constraint WHERE conname='db03_handoff_exact_d1_student_number_person'),'deferred source permits READY before consumed');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_number_same_application'),'old exact application number lineage');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_identity_same_application'),'old same application Person lineage');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_policy_snapshot_same_application_version'),'old policy version lineage');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_principal_approval_requires_consumed_handoff' AND condeferrable AND condeferred),'approval still demands consumed handoff');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_exact_principal_approval' AND condeferrable AND condeferred),'reciprocal approval integrity preserved');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_handoff_number_one_link'),'allocation not reused by second handoff');
SELECT ok((SELECT count(*)=3 FROM pg_class WHERE oid IN('app_private.students'::regclass,'app_private.admission_student_handoffs'::regclass,'app_private.admission_number_allocations'::regclass) AND relrowsecurity AND relforcerowsecurity),'three private tables retain forced RLS');
SELECT ok((SELECT count(*)=2 FROM pg_trigger WHERE tgname IN('db03_handoff_mutation_disabled','db03_number_allocations_mutation_disabled') AND NOT tgisinternal AND tgenabled='O'),'both deny-all mutation triggers remain');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_student_handoffs','INSERT'),'client handoff forging unavailable');
SELECT ok(NOT has_table_privilege('schoolos_workflow_executor','app_private.students','INSERT'),'workflow cannot directly insert Student');
SELECT ok(NOT has_table_privilege('schoolos_student_executor','app_private.admission_student_handoffs','INSERT'),'D1 executor cannot forge approval handoff');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'final approval still disabled');
SELECT ok((SELECT count(*)=0 FROM app_private.operation_contracts WHERE code='student.create' AND enabled),'D1 student create still disabled');
SELECT ok((SELECT count(*)=0 FROM app_private.admission_student_handoffs),'no handoff created in fixture');
SELECT ok((SELECT count(*)=0 FROM app_private.students),'no Student created in fixture');
SELECT * FROM finish();
ROLLBACK;
